const featuredOrder=['monoblock','bivacuum','oltreetrusco','poliedro','compluvio','presence','soundplace'];
projects.sort((a,b)=>featuredOrder.indexOf(a.id)-featuredOrder.indexOf(b.id));
projects.forEach((p,i)=>p.featured=i<4);
const technicalCaptions={};
const sheet=(image,it,en,kind='detail')=>{technicalCaptions[image]=P(it,en);return {image,title:P(it,en),kind}};
const chapter=(it,en,textIt,textEn)=>({title:P(it,en),body:P(textIt,textEn)});
const notebooks={
monoblock:{question:P('Che cosa succede quando il prodotto ha finito di servirci?','What happens when a product is no longer useful to us?'),lens:P('La mia ricerca parte da una sedia ordinaria per allargare il campo del progetto: dall’oggetto alle condizioni che ne determinano il destino.','My research starts with an ordinary chair and broadens the scope of design: from the object to the conditions that determine its future.'),chapters:[chapter('Una sedia, una contraddizione','One chair, one contradiction','La tesi usa il Monobloc come protagonista di una domanda sul design industriale. La semplicità del prodotto e l’efficienza del processo non risolvono da sole la gestione dopo l’uso. Il percorso intreccia la storia delle sedie in plastica, le tecniche produttive e il problema del fine vita. Le sedie storiche sono oggetti della ricerca, non prodotti disegnati per questo progetto.','The thesis uses the Monobloc to question industrial design. Simplicity and production efficiency do not, by themselves, resolve what happens after use. The exhibition connects the history of plastic chairs, manufacturing techniques and end-of-life issues. Historical chairs are subjects of research, not products designed for this project.'),chapter('Lo spazio come argomento','Space as an argument','Una griglia modulare di alluminio, pannelli e tende semitrasparenti organizzano la mostra. I moduli quadrati di 50 × 50 cm costruiscono un’infrastruttura di sospensione, mentre i tessuti definiscono soglie senza isolare completamente le aree. La possibilità di separare alluminio, acciaio e tessuto fa parte del tema: l’allestimento deve interrogarsi anche sul proprio smontaggio.','A modular aluminium grid, panels and translucent curtains organise the exhibition. Square 50 × 50 cm modules create a suspension infrastructure, while fabric defines thresholds without fully isolating each area. Separating aluminium, steel and fabric is part of the argument: the exhibition must also consider its own disassembly.'),chapter('Produrre, lasciare, ricominciare','Produce, leave, repeat','Sei stampanti 3D inclinate producono oggetti che, una volta completati, scivolano a terra. La macchina riparte e nessuno raccoglie il risultato: l’accumulo rende visibile il tempo della mostra. L’installazione mette in discussione una produzione che sa controllare ogni fase fino all’uscita dell’oggetto, ma non ciò che avviene dopo.','Six tilted 3D printers produce objects that slide onto the floor when complete. The machine starts again and nobody collects the result: accumulation makes the exhibition’s duration visible. The installation questions production that controls every stage until the object leaves the machine, but not what happens afterwards.')],technical:[sheet('monoblock-30','Planimetria — parte I','Floor plan — part I','plan'),sheet('monoblock-31','Planimetria — parte II','Floor plan — part II','plan'),...[32,33,34,35].map(n=>sheet('monoblock-'+n,'Disposizione e collezione — '+(n-31),'Layout and collection — '+(n-31),'plan')),sheet('monoblock-36','Griglia e sistema di sospensione','Grid and suspension system'),sheet('monoblock-37','Connessioni meccaniche','Mechanical connections'),sheet('monoblock-38','Tende e partizioni','Curtains and partitions'),sheet('monoblock-39','Installazione delle stampanti 3D','3D printer installation'),sheet('monoblock-40','Progetto della luce','Lighting design'),sheet('monoblock-41','Apparecchi illuminanti','Lighting fixtures'),sheet('monoblock-42','Materiali — abaco I','Materials — schedule I'),sheet('monoblock-43','Materiali — abaco II','Materials — schedule II'),sheet('monoblock-44','Identità e tipografia','Identity and typography'),sheet('monoblock-45','Il colore nel tempo','Colour over time')]},
bivacuum:{question:P('Come può uno spazio minimo accogliere modi diversi di stare insieme?','How can a minimum space accommodate different ways of being together?'),lens:P('La montagna incontra il mio interesse per i sistemi trasformabili: partire dai gesti di chi arriva, si riposa e riparte.','The mountains meet my interest in transformable systems: beginning with the gestures of arriving, resting and setting off again.'),chapters:[chapter('Arrivare e trovare riparo','Arriving and finding shelter','Il brief prevede almeno otto posti, uso nelle diverse stagioni e una struttura preassemblata con montaggio ridotto sul posto. Il contesto è un terrazzo naturale sul percorso verso la Grignetta, pensato come punto di riparo e sosta. La compattezza risponde sia all’abitare sia al trasporto e all’installazione.','The brief calls for at least eight places, use across seasons and a preassembled structure requiring limited on-site work. The setting is a natural terrace on the way to the Grignetta, conceived as a place for shelter and rest. Compactness addresses living, transport and installation.'),chapter('Il soffitto libera il pavimento','The ceiling frees the floor','Una rete di binari permette di appendere e spostare le amache. Di giorno l’interno diventa uno spazio comune; di notte le superfici sospese accolgono il riposo. Tavoli a parete ripiegabili e sedute integrate riducono gli ingombri fissi: la trasformazione nasce da operazioni semplici, leggibili negli schizzi e nelle sezioni.','A network of rails allows hammocks to be suspended and moved. During the day the interior becomes shared space; at night suspended surfaces provide rest. Folding wall tables and integrated seating reduce fixed obstructions: transformation comes from simple operations, described in sketches and sections.'),chapter('Pensare per strati e connessioni','Thinking through layers and connections','L’involucro studiato nel progetto combina compensato interno, struttura lignea, vuoto tecnico, barriera al vapore, isolamento in lana di pecora, camera ventilata e rivestimento metallico. Le tavole approfondiscono anche le fondazioni a vite e il sistema fotovoltaico a inclinazione regolabile. Sono soluzioni di progetto da leggere insieme, alla scala del dettaglio e dell’insieme.','The proposed envelope combines internal plywood, a timber structure, a service cavity, vapour barrier, sheep-wool insulation, a ventilated cavity and metal cladding. The drawings also study screw foundations and adjustable photovoltaic panels. These design proposals are best read together, at both detail and overall scales.')],technical:[sheet('bivacuum-pianta-giorno','Sezione ambientata — giorno','Context section — day','section'),sheet('bivacuum-pianta-notte','Sezione ambientata — notte','Context section — night','section'),sheet('bivacuum-pianta','Pianta di studio','Study plan','plan'),sheet('bivacuum-10-roof-plan','Pianta della copertura','Roof plan','plan'),sheet('bivacuum-11-section-day-long','Sezione longitudinale — giorno','Longitudinal section — day','section'),sheet('bivacuum-13-section-night-long','Sezione longitudinale — notte','Longitudinal section — night','section'),sheet('bivacuum-12-section-day-cross','Sezione trasversale','Cross section','section'),sheet('bivacuum-09-elevation-west','Prospetto ovest','West elevation','section'),sheet('bivacuum-binari','Griglia e binari','Grid and rails'),sheet('bivacuum-tavoli','Tavoli ripiegabili','Folding tables'),sheet('bivacuum-16-envelope-stratigraphy','Stratigrafia dell’involucro','Envelope layers'),sheet('bivacuum-viti','Dettaglio delle connessioni','Connection detail'),sheet('bivacuum-17-screw-foundation','Fondazioni a vite','Screw foundations'),sheet('bivacuum-18-pv-tilt','Fotovoltaico orientabile','Adjustable photovoltaics'),sheet('bivacuum-tavola-1','Tavola generale 01','General board 01','board'),sheet('bivacuum-tavola-2','Tavola generale 02','General board 02','board')]},
oltreetrusco:{question:P('Può un allestimento cambiare il nostro modo di attraversare una storia?','Can an exhibition change how we move through a story?'),lens:P('Mi interessa il confine quando diventa una possibilità: orientare il visitatore e poi lasciargli libertà.','I am interested in boundaries as possibilities: guiding visitors, then giving them freedom.'),chapters:[chapter('Lo sconfinamento come regola','Crossing boundaries as a principle','Oltre Etrusco mette in relazione passato e presente attraverso il tema dello sconfinamento. Il percorso non è una sequenza neutra di oggetti: cambia il grado di libertà del visitatore. Nella prima sala il limite indica dove passare; nelle successive la struttura si apre e la lettura diventa più personale.','Oltre Etrusco connects past and present through the crossing of boundaries. The route is not a neutral sequence of objects: it changes the visitor’s degree of freedom. In the first room boundaries define the route; later the structure opens up and interpretation becomes more personal.'),chapter('Dal percorso alla scoperta','From a route to discovery','La seconda sala interrompe progressivamente i confini e la terza distribuisce gli elementi nello spazio. La sala dedicata alla Tomba degli Auguri introduce un altro momento del racconto; le sale finali e il corridoio lavorano con soglie più leggere e tende. Le piante permettono di seguire questa progressione stanza per stanza.','The second room progressively interrupts boundaries; the third distributes elements throughout the space. The room dedicated to the Tomb of the Augurs introduces another chapter, while final rooms and the corridor use lighter thresholds and curtains. The plans reveal this progression room by room.'),chapter('Una struttura che si adatta','An adaptable structure','Oltre è un sistema di strutture metalliche modulari con supporti regolabili. L’esploso descrive come le parti costruiscono l’insieme; i dettagli mostrano il passaggio dalla regola spaziale al dispositivo che sostiene e presenta i reperti. La flessibilità del sistema rende possibili configurazioni differenti lungo il percorso.','Oltre is a system of modular metal structures with adjustable supports. The exploded drawing describes how the parts form the whole; details connect the spatial principle to the device supporting and displaying artefacts. System flexibility enables different configurations along the route.')],technical:[sheet('oltre-sala1','Sala 1 — percorso guidato','Room 1 — guided route','plan'),sheet('oltre-sala2','Sala 2 — confine permeabile','Room 2 — permeable boundary','plan'),sheet('oltre-sala3a','Sala 3 — studio I','Room 3 — study I','plan'),sheet('oltre-sala3b','Sala 3 — studio II','Room 3 — study II','plan'),sheet('oltre-corridoio','Sale finali e corridoio','Final rooms and corridor','plan'),sheet('oltre-esploso','Esploso dell’allestimento','Exhibition exploded view','board'),sheet('oltre-dettagli','Dettagli del sistema Oltre','Oltre system details'),...[2,3,4,5].map(n=>sheet('oltreetrusco_tavola_0'+n,'Tavola di progetto 0'+n,'Project board 0'+n,'board'))]},
poliedro:{question:P('Come dare forma a un incontro senza decidere come debba avvenire?','How can we shape an encounter without deciding how it should happen?'),lens:P('Parto dalle persone e dalle distanze tra loro. Il modulo è uno strumento per lasciare spazio a relazioni diverse.','I start with people and the distances between them. A module is a tool for making room for different relationships.'),chapters:[chapter('Piccole isole sociali','Small social islands','POLIEDRO nasce per favorire l’interazione tra giovani nello spazio pubblico. Una panca e un elemento doppio si aggregano in configurazioni flessibili: la disposizione invita alla sosta senza imporre un unico modo di sedersi o di stare in gruppo.','POLIEDRO is designed to encourage interaction among young people in public space. A bench and a double element combine in flexible configurations: their arrangement invites people to stay without prescribing one way of sitting or gathering.'),chapter('La geometria diventa uso','Geometry becomes use','La matrice esagonale costruisce una famiglia di volumi. Altezze differenti, superfici di appoggio e cavità articolano il sistema in sedute e punti di relazione. I dettagli mettono in evidenza gli spessori, le inclinazioni e gli accorgimenti per il drenaggio.','A hexagonal matrix creates a family of volumes. Different heights, supporting surfaces and cavities articulate seats and points of connection. The details show thicknesses, slopes and provisions for drainage.'),chapter('Una luce per prolungare la sosta','A light that extends the time together','La lampada completa l’isola sociale e introduce un centro luminoso. Il progetto accosta la massa del calcestruzzo a un corpo diffusore in policarbonato. A matter of presence porta lo stesso sistema in una dimensione espositiva, dove riflessi e penombra amplificano la percezione della materia.','The lamp completes the social island and introduces a luminous centre. The design places the mass of concrete alongside a polycarbonate diffuser. A matter of presence brings the system into an exhibition setting, where reflections and low light amplify the perception of matter.')],technical:[sheet('poliedro-tavola-15','Concept e sistema modulare','Concept and modular system','board'),sheet('poliedro-tavola-16','Disegni tecnici e dettagli costruttivi','Technical drawings and construction details','board'),sheet('poliedro_dettaglio_seduta_03','Seduta — cavità e raccordi','Seat — cavities and connections'),sheet('poliedro_dettaglio_seduta_04','Seduta — drenaggio','Seat — drainage'),sheet('poliedro_lampada','Lampada — modulo luminoso','Lamp — light module')]},
compluvio:{question:P('E se fosse l’acqua a disegnare lo spazio?','What if water could shape space?'),lens:P('Leggere un fenomeno naturale e trasformarlo in una regola costruttiva, per uno spazio da vivere insieme.','Reading a natural phenomenon and translating it into a building principle for a shared space.'),chapters:[chapter('Coltivare relazioni','Growing relationships','Il progetto per Cascina Linterno integra una serra sociale e terapeutica nel rapporto tra costruito e paesaggio. La coltivazione diventa occasione di attività condivisa, dentro un ambiente protetto ma visivamente aperto all’esterno.','The project for Cascina Linterno integrates a social and therapeutic greenhouse into the relationship between buildings and landscape. Cultivation becomes a shared activity in an environment that is sheltered yet visually open to the outside.'),chapter('La sezione raccoglie','The section collects','Le due volte si incontrano in una depressione centrale che convoglia la pioggia verso la raccolta. Il sistema studiato collega serbatoio e irrigazione a bassa pressione. Il recupero dell’acqua è un obiettivo progettuale: forma della copertura e organizzazione della coltivazione sono pensate insieme.','The two vaults meet in a central valley directing rain towards collection. The proposed system connects a reservoir with low-pressure irrigation. Water recovery is a design objective: the roof form and the organisation of cultivation are considered together.')],technical:[sheet('compluvio_sezioni_tipo','Copertura, pianta e sezione','Roof, plan and section','plan'),sheet('compluvio_assonometria_luogo','Inserimento a Cascina Linterno','Cascina Linterno site context','plan')]},
presence:{question:P('Quanto può cambiare un oggetto quando cambia lo spazio intorno?','How much can an object change when the surrounding space changes?'),lens:P('La luce e il riflesso sono materiali di progetto: cambiano la distanza, la scala e il modo in cui ci fermiamo.','Light and reflection are design materials: they change distance, scale and the way we pause.'),chapters:[chapter('Un paesaggio interno','An interior landscape','L’allestimento racconta POLIEDRO attraverso un’immagine minerale. La materia scura delle sedute, il terreno di pietre e la penombra costruiscono un’esperienza che richiama il paesaggio montano senza riprodurlo letteralmente.','The exhibition tells the story of POLIEDRO through a mineral landscape. Dark seating, a ground of stones and low light evoke the mountains without reproducing them literally.'),chapter('Moltiplicare la presenza','Multiplying presence','Gli specchi frammentano i punti di vista e moltiplicano i moduli. La zona centrale concentra la sosta e l’incontro; le tende modulano il rapporto con l’esterno. Piante e prospetti chiariscono la relazione tra percorso, quinte e area collettiva.','Mirrors fragment viewpoints and multiply modules. The central area concentrates rest and encounter; curtains mediate the outside. Plans and elevations clarify the relationship between the route, screens and collective area.')],technical:[sheet('presence_prospetti','Pianta, sezioni e prospetti','Plan, sections and elevations','plan')]},
soundplace:{question:P('Qual è il minimo necessario per creare un luogo di incontro?','What is the minimum needed to create a meeting place?'),lens:P('Un oggetto può essere anche un servizio: mi interessa ciò che accade prima, durante e dopo il suo utilizzo.','An object can also be a service: I am interested in what happens before, during and after its use.'),chapters:[chapter('Dal bisogno al dispositivo','From a need to a device','La ricerca a Morbegno individua il bisogno di luoghi per incontrarsi e condividere musica in autonomia. Walking Tree risponde con un modulo mobile di 80 × 160 cm che integra un albero, due sedute e un risonatore passivo per smartphone.','Research in Morbegno identifies the need for places to meet and independently share music. Walking Tree responds with a mobile 80 × 160 cm module integrating a tree, two seats and a passive smartphone resonator.'),chapter('Progettare l’esperienza completa','Designing the complete experience','Il servizio immaginato attraversa cinque momenti: stimolo iniziale, prenotazione, attivazione, esperienza e feedback. Il telefono aiuta a trovare e attivare il modulo; la parte centrale del progetto rimane l’incontro tra persone. L’app mostrata negli schizzi è una proposta di servizio.','The proposed service spans five stages: initial trigger, booking, activation, experience and feedback. A phone helps find and activate the module; the central experience remains the encounter between people. The app shown in sketches is a service proposal.')],technical:[sheet('soundplace_assonometria','Assonometria del modulo','Module axonometric view'),sheet('soundplace_luogo_ponte','Ponte Vanoni — localizzazione','Ponte Vanoni — location','plan'),sheet('soundplace_storyboard','Storyboard — esperienza di servizio','Storyboard — service experience','board')]}
};
projects.forEach(p=>Object.assign(p,notebooks[p.id]));
projects[0].text=P('L’allestimento collega storia, materia e responsabilità. Griglia, pannelli e tende costruiscono il percorso; un’installazione di sei stampanti 3D produce oggetti che diventano subito scarto. L’accumulo rende visibile ciò che la produzione lascia dopo di sé.','The exhibition connects history, matter and responsibility. A grid, panels and curtains shape the route; an installation of six 3D printers produces objects that immediately become waste. Accumulation makes visible what production leaves behind.');

Object.assign(imageDimensions,{"monoblock-32": {"width": 2800, "height": 1981}, "monoblock-33": {"width": 2800, "height": 1981}, "monoblock-34": {"width": 2800, "height": 1981}, "monoblock-35": {"width": 2800, "height": 1981}, "monoblock-40": {"width": 2800, "height": 1981}, "monoblock-41": {"width": 2800, "height": 1981}, "monoblock-42": {"width": 2800, "height": 1981}, "monoblock-43": {"width": 2800, "height": 1981}, "monoblock-44": {"width": 2800, "height": 1981}, "monoblock-45": {"width": 2800, "height": 1981}, "poliedro-tavola-15": {"width": 2800, "height": 1981}, "poliedro-tavola-16": {"width": 2800, "height": 1981}, "bivacuum-pianta-giorno": {"width": 1980, "height": 2800}, "bivacuum-pianta-notte": {"width": 1980, "height": 2800}, "bivacuum-tavola-1": {"width": 2800, "height": 1981}, "bivacuum-tavola-2": {"width": 2800, "height": 1981}, "bivacuum-viti": {"width": 1980, "height": 2800}, "bivacuum-binari": {"width": 1983, "height": 2800}, "bivacuum-pianta": {"width": 2800, "height": 1981}, "bivacuum-tavoli": {"width": 1954, "height": 2800}, "oltre-dettagli": {"width": 2800, "height": 1981}, "oltre-esploso": {"width": 2800, "height": 1981}, "oltre-sala1": {"width": 2800, "height": 1981}, "oltre-sala2": {"width": 2800, "height": 1981}, "oltre-sala3a": {"width": 2800, "height": 1981}, "oltre-sala3b": {"width": 2800, "height": 1981}, "oltre-corridoio": {"width": 2800, "height": 1981}});
